<script setup lang="ts">
import type { KnowledgeSource } from "../../api/knowledgeSources";

defineProps<{ sources: readonly KnowledgeSource[]; disabled: boolean }>();
const emit = defineEmits<{ toggle: [source: KnowledgeSource, enabled: boolean]; remove: [source: KnowledgeSource]; sync: [source: KnowledgeSource]; viewDocuments: [source: KnowledgeSource] }>();
const typeLabels = { local_folder: "本地文件夹", obsidian_vault: "Obsidian Vault", temporary_import: "临时导入" } as const;
const statusLabels = { idle: "等待同步", scanning: "同步中", completed: "已同步", completed_with_errors: "同步含错误", unavailable: "不可用" } as const;
function formatTime(value: string | null): string { return value ? new Intl.DateTimeFormat("zh-CN", { dateStyle: "medium", timeStyle: "short" }).format(new Date(value)) : "尚未同步"; }
</script>

<template>
  <p v-if="sources.length === 0" class="empty-state">当前筛选条件下没有知识来源。</p>
  <ul v-else class="source-list"><li v-for="source in sources" :key="source.id" class="source-row"><div class="source-main"><span class="source-icon" aria-hidden="true">▰</span><div><h3>{{ source.name }}</h3><p class="source-path">{{ source.root_path }}</p><span class="type-pill">{{ typeLabels[source.source_type] }}</span></div></div><div class="statistics"><span><b>{{ source.stats.total_files }}</b> 个文件</span><span><b>{{ source.stats.indexed }}</b> 已索引</span><span><b>{{ source.stats.pending }}</b> 待处理</span><span :class="{ failed: source.stats.failed > 0 }"><b>{{ source.stats.failed }}</b> 异常</span></div><div class="source-status"><span>上次同步：{{ formatTime(source.last_sync_time) }}</span><strong :class="`status-${source.sync_status}`">● {{ statusLabels[source.sync_status] }}</strong><em v-if="source.error_message" role="alert">{{ source.error_message }}</em></div><div class="source-actions"><button type="button" :disabled="disabled || source.sync_status === 'scanning' || !source.enabled" @click="emit('sync', source)">{{ source.sync_status === 'scanning' ? '同步中' : '同步' }}</button><label class="switch"><input type="checkbox" :checked="source.enabled" :disabled="disabled" @change="emit('toggle', source, ($event.target as HTMLInputElement).checked)"><span></span><i class="sr-only">{{ source.enabled ? '已启用' : '已停用' }}</i></label><button class="document-link" type="button" @click="emit('viewDocuments', source)">查看文档 →</button><button class="remove-action" type="button" :disabled="disabled" @click="emit('remove', source)">⋮</button></div></li></ul>
</template>

<style scoped>
