er{position:absolute;top:2px;left:2px;width:16px;height:16px;border-radius:50%;background:#fff;box-shadow:0 1px 2px rgba(0,0,0,.15);content:""}.switch input:checked+span{background:var(--color-primary)}.switch input:checked+span::after{transform:translateX(16px)}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}.empty-state{margin:0;padding:32px 0;color:var(--text-muted);text-align:center}@media(max-width:1050px){.source-row{grid-template-columns:1fr 1fr}.source-actions{justify-content:flex-end}}@media(max-width:650px){.source-row{grid-template-columns:1fr}.source-actions{justify-content:flex-start}}
